
/*
1. asset_type_conf modify ssh_collect_script type
2. Server and Virtual machine add ssh_collect_script
 */
ALTER TABLE `asset_type_conf`
    MODIFY COLUMN IF EXISTS`ssh_collect_script` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '';


UPDATE asset_type_conf SET ssh_collect_script = '#!/bin/bash\n# os\nos_platform=\"Linux\"\nos_hostName=$(uname -n)\nos_manufacturer=$(uname -o)\nos_machine=$(uname -m)\nos_bitness=32\n[[ $os_machine == *64* ]] && os_bitness=64\n\nos_family=\"\"\nos_codeName=\"\"\nos_versionId=\"unknown\"\nwhile read line  \ndo  \n    if [[ $line =~ [[:space:]]release[[:space:]] ]]; then\n        os_family=$(echo \"$line\" | awk -F \' release \' \'{print $1}\')\n        tempStr=$(echo \"$line\" | awk -F \' release \' \'{print $2}\')\n	IFS=\'()\' read -ra arr <<< \"$tempStr\"\n	if [ ${#arr[@]} -gt 0 ]; then\n	    os_versionId=$(echo \"${arr[0]}\" | awk \'{$1=$1};1\')\n	fi\n	if [ ${#arr[@]} -gt 1 ]; then\n	    os_codeName=$(echo \"${arr[1]}\" | awk \'{$1=$1};1\')\n	fi\n    elif [[ $line =~ [[:space:]]VERSION[[:space:]] ]]; then\n	os_family=$(echo \"$line\" | awk -F \' VERSION \' \'{print $1}\')\n        tempStr=$(echo \"$line\" | awk -F \' VERSION \' \'{print $2}\')\n	IFS=\'()\' read -ra arr <<< \"$tempStr\"\n	if [ ${#arr[@]} -gt 0 ]; then\n	    os_versionId=$(echo \"${arr[0]}\" | awk \'{$1=$1};1\')\n	fi\n	if [ ${#arr[@]} -gt 1 ]; then\n	    os_codeName=$(echo \"${arr[1]}\" | awk \'{$1=$1};1\')\n	fi\n    fi\ndone < \"/etc/system-release\"\n\nos_versionInfo+=\"$os_versionId\"\nos_kernelRelease=$(uname -r)\n[ -n \"$os_codeName\" ] && os_versionInfo+=\" ($os_codeName)\"\n[ -n \"$os_kernelRelease\" ] && os_versionInfo+=\" build $os_kernelRelease\"\n\nos_ipv4DefaultGateway=$(ip -4 route show default | awk \'/default/ {print $3; exit}\')\nos_ipv6DefaultGateway=$(ip -6 route show default | awk \'/default/ {print $3; exit}\')\n\nos=\'{\n    \"bitness\": \'$os_bitness\',\n    \"hostName\": \"\'$os_hostName\'\",\n    \"versionInfo\": \"\'$os_versionInfo\'\",\n    \"family\": \"\'$os_family\'\",\n    \"platform\": \"\'$os_platform\'\",\n    \"manufacturer\": \"\'$os_manufacturer\'\",\n    \"ipv4DefaultGateway\": \"\'$os_ipv4DefaultGateway\'\",\n    \"ipv6DefaultGateway\": \"\'$os_ipv6DefaultGateway\'\"\n}\'\n\n# memory\nprocess_value() {\n    local keyword=\"$1\"\n    local value=\"${array[1]}\"\n    local unit=\"${array[2]:-}\"\n\n    if [ ${#array[@]} -lt 3 ]; then\n        value=0\n    fi\n\n    [ \'kB\' = \"$unit\" ] && value=$(($value * 1024))\n\n    case \"$keyword\" in\n        \'MemTotal:\') mem_memTotal=$value ;;\n        \'SwapTotal:\') mem_swapTotal=$value ;;\n        \'CommitLimit:\') mem_virtualMax=$value ;;\n    esac\n}\n\nwhile read line; do  \n    IFS=\' \' read -r -a array <<< \"$line\"\n    for element in \"${array[@]}\"; do\n        case \"$element\" in\n            \'MemTotal:\'|\'SwapTotal:\'|\'CommitLimit:\') process_value \"$element\" ;;\n        esac\n    done\ndone < \"/proc/meminfo\"\n\nmemory=\'{\n    \"total\": \'$mem_memTotal\',\n    \"swapTotal\": \'$mem_swapTotal\',\n    \"virtualMax\": \'$mem_virtualMax\'\n}\'\n\n\n# cpu\ncpu_contextSwitches=0\ncpu_interrupts=0\n\nwhile read line \ndo  \n    IFS=\' \' read -r -a array <<< \"$line\"\n    for element in \"${array[@]}\"\n    do\n        case $element in\n            ctxt) cpu_contextSwitches=\"${array[1]}\" ;;\n            intr) cpu_interrupts=\"${array[1]}\" ;;\n        esac\n    done\ndone < \"/proc/stat\"\n\ncpu_cpu64bit=$(grep \'flags\' /proc/cpuinfo | grep -qw \'lm\' && echo true || echo false)\ncpu_name=$(cat /proc/cpuinfo | grep -E \'model name|Processor\' | sort | uniq | awk -F \':\' \'NR==1 {gsub(/^[ \\t]+/, \"\", $2); print $2}\')\ncpu_model=$(cat /proc/cpuinfo | grep -E \'model|CPU part\' | sort | uniq | awk -F \':\' \'NR==1 {gsub(/^[ \\t]+/, \"\", $2); print $2}\')\ncpu_stepping=$(cat /proc/cpuinfo | grep -E \'stepping\' | sort | uniq | awk -F \':\' \'NR==1 {gsub(/^[ \\t]+/, \"\", $2); print $2}\')\ncpu_vendor=$(cat /proc/cpuinfo | grep -E \'vendor_id|CPU implementer\' | sort | uniq | awk -F \':\' \'NR==1 {gsub(/^[ \\t]+/, \"\", $2); print $2}\')\ncpu_family=$(cat /proc/cpuinfo | grep -E \'cpu family\' | sort | uniq | awk -F \':\' \'NR==1 {gsub(/^[ \\t]+/, \"\", $2); print $2}\')\ncpu_microcode=$(cat /proc/cpuinfo | grep -E \'microcode\' | sort | uniq | awk -F \':\' \'NR==1 {gsub(/^[ \\t]+/, \"\", $2); print $2}\')\n\ncpu_identifier=\"\"\nif [ \"$cpu_vendor\" = \"GenuineIntel\" ]; then\n    [ \"$cpu_cpu64bit\" = true ] && cpu_identifier+=\"Intel64\" || cpu_identifier+=\"x86\"\nelse\n    cpu_identifier+=\"$vendor\"\nfi\n\ncpu_identifier+=\" Family $cpu_family Model $cpu_model Stepping $cpu_stepping\"\n\ncpu_logicalProcessorCount=$(lscpu -p | egrep -v \'^#\' | wc -l)\ncpu_physicalProcessorCount=$(lscpu -p | egrep -v \'^#\' | sort -u -t, -k 2,4 | wc -l)\ncpu_physicalPackageCount=$(($(grep \"^physical id\" /proc/cpuinfo | awk \'{print $4}\' | sort -un | tail -1)+1))\n\ncpu=\'{\n    \"cpu64bit\": \'$cpu_cpu64bit\',\n    \"identifier\": \"\'$cpu_identifier\'\",\n    \"stepping\": \"\'$cpu_stepping\'\",\n    \"contextSwitches\": \"\'$cpu_contextSwitches\'\",\n    \"microarchitecture\": \"\'$cpu_microcode\'\",\n    \"vendor\": \"\'$cpu_vendor\'\",\n    \"name\": \"\'$cpu_name\'\",\n    \"interrupts\": \"\'$cpu_interrupts\'\",\n    \"model\": \"\'$cpu_model\'\",\n    \"family\": \"\'$cpu_family\'\",\n    \"logicalProcessorCount\": \"\'$cpu_logicalProcessorCount\'\",\n    \"physicalProcessorCount\": \"\'$cpu_physicalProcessorCount\'\",\n    \"physicalPackageCount\": \"\'$cpu_physicalPackageCount\'\"\n}\'\n\n\n# disk\nsfdiskList=$(sfdisk -s | awk -F \':\' \'{print $1}\' | grep \'/dev/sd\')\n\ndiskJSONArray=\"[\"\nfor item in $sfdiskList\ndo  \n    name=$(echo $item | sed \'s/\\/dev\\///\')\n    size=$(lsblk -o NAME,SIZE -ab | grep -w \"$name\" | awk \'{print $2}\')\n\n    model=$(echo $temp_model_str | awk -v exclude=$name \'{for(i=1; i<=NF; i++) {if ($i != exclude) {printf \"%s_\", $i}}}\')\n    model=${model%_}\n\n    model=$(lsblk -o NAME,MODEL -ab | grep -w \"$name\" | awk -v exclude=\"$name\" \'{for(i=1; i<=NF; i++) {if ($i != exclude) {printf \"%s_\", $i}}}\')\n    model=${model%_}\n\n    serial=$(lsblk -o NAME,SERIAL -ab | grep -w \"$name\" | awk -v exclude=\"$name\" \'{for(i=1; i<=NF; i++) {if ($i != exclude) {printf \"%s_\", $i}}}\')\n    serial=${serial%_}\n\n    diskJSONObject=\"{\\\"size\\\":\\\"$size\\\",\\\"serial\\\":\\\"$serial\\\",\\\"name\\\":\\\"/dev/$name\\\",\\\"model\\\":\\\"$model\\\"},\"\n    diskJSONArray+=\"$diskJSONObject\"\ndone\ndiskJSONArray=\"${diskJSONArray%,}]\"\n\n\n# networkIF\nnetNameList=$(ls /sys/class/net)\n\nnetJSONArray=\"[\"\nfor ifName in $netNameList\ndo  \n   ifDir=$(stat -c %F \"/sys/class/net/$ifName/statistics\" 2>/dev/null)\n   ifType=0\n   ifIndex=0\n   mtu=0\n   speed=0\n   address=\"\"\n   ifalias=\"\"\n   ifOperStatus=2\n   if [[ \'directory\' = $ifDir ]]; then\n       ifType=$(awk \'NR==1 {print; exit}\' /sys/class/net/$ifName/type 2>/dev/null)\n       ifIndex=$(awk \'NR==1 {print; exit}\' /sys/class/net/$ifName/ifindex 2>/dev/null)\n       mtu=$(awk \'NR==1 {print; exit}\' /sys/class/net/$ifName/mtu 2>/dev/null)\n       speedMiB=$(awk \'NR==1 {print; exit}\' /sys/class/net/$ifName/speed 2>/dev/null)\n       if (( speedMiB > 0 )); then\n         speed=$((speedMiB * 1024 * 1024))\n       fi\n\n       address=$(awk \'NR==1 {print; exit}\' /sys/class/net/$ifName/address 2>/dev/null)\n       ifalias=$(awk \'NR==1 {print; exit}\' /sys/class/net/$ifName/ifalias 2>/dev/null)\n       operstate=$(awk \'NR==1 {print; exit}\' /sys/class/net/$ifName/operstate 2>/dev/null)\n       if [ \'up\' = \"$operstate\" ]; then\n           ifOperStatus=1\n       fi\n   fi\n\n   iPv4addr=$(ip addr show $ifName 2>/dev/null | grep \"inet\\b\" | awk \'{print $2}\' | cut -d/ -f1 | awk \'{arr = arr \"\\\"\" $0 \"\\\",\"} END {print \"[\" substr(arr, 1, length(arr)-1) \"]\"}\')\n   iPv6addr=$(ip addr show $ifName 2>/dev/null | grep \"inet6\\b\" | awk \'{print $2}\' | cut -d/ -f1 | awk \'{arr = arr \"\\\"\" $0 \"\\\",\"} END {print \"[\" substr(arr, 1, length(arr)-1) \"]\"}\')\n   subnetMasks=$(ip addr show $ifName 2>/dev/null | grep \"inet\\b\" | awk \'{print $2}\' | cut -d/ -f2 | awk \'{arr = arr \"\\\"\" $0 \"\\\",\"} END {print \"[\" substr(arr, 1, length(arr)-1) \"]\"}\')\n\n   netJSONObject=\"{\\\"ifAlias\\\":\\\"$ifAlias\\\",\\\"ifType\\\":\\\"$ifType\\\",\\\"name\\\":\\\"$ifName\\\",\\\"index\\\":\\\"$ifIndex\\\",\\\"ifOperStatus\\\":\\\"$ifOperStatus\\\",\\\"speed\\\":\\\"$speed\\\",\\\"macaddr\\\":\\\"$address\\\",\\\"mtu\\\":\\\"$mtu\\\",\\\"iPv4addr\\\":$iPv4addr,\\\"iPv6addr\\\":$iPv6addr,\\\"subnetMasks\\\":$subnetMasks},\"\n   netJSONArray+=\"$netJSONObject\"\ndone\nnetJSONArray=\"${netJSONArray%,}]\"\n\nbasicInfoJson=\"{\\\"os\\\": $os, \\\"memory\\\": $memory, \\\"cpu\\\": $cpu, \\\"disk\\\": $diskJSONArray, \\\"networkIF\\\": $netJSONArray}\"\necho \"$basicInfoJson\"'
where name in ("Server","Virtual machine");